  "explanation": "BCR遺伝子の再編成はRAG1-RAG2複合体が組換えシグナル配列（RSS）を認識して始まり、重鎖から先に進む。重鎖はDセグメントを挟むためD-J結合→V-DJ結合の2段階、軽鎖にはDがないためV-Jの1段階で終わる。順番を問う設問では「まずD-J」と答える。重鎖の再編成が成功するとpre-BCRが発現し（Q16）、それを合図に軽鎖の再編成が始まる。　▶該当スライド：先天性免疫不全症 p54・p55／老化と免疫 p33・p34",
  "choiceNotes": [
   "誤り。V-D結合は先に起きない。DがJと結合してDJができてから、VがDJへ結合する。",
   "正しい＝正解。重鎖のD-J結合が最初に起こる。",
   "誤り。重鎖にはDセグメントが介在するため、VとJが直接つながることはない。",
   "誤り。軽鎖（κ・λ）にはDセグメントが存在しない。",
   "誤り。軽鎖のV-J再編成は、重鎖再編成とpre-BCR発現より後。"
  ],
