  "choiceNotes": [
   "誤り。IgAも胎盤をほとんど通過しないが、先天感染の指標として標準的に使うのはIgM。",
   "誤り。IgDは診断指標として用いない。",
   "誤り。IgEは用いない。",
   "誤り。母親由来のIgGが胎盤を通って移行しているため、存在しても胎児の感染を示さない。",
   "正しい＝正解。IgMは胎盤を通過しないため、新生児血中のIgMは胎児自身の抗体産生を示す。"
  ],
