  "explanation": "胎児は母親から見れば半分が非自己（父親由来のHLAを持つ移植片）にあたるため、子宮は免疫特権部位として扱われる。胎盤絨毛細胞は多型性の高いHLA-A・B・Cをほとんど発現しない代わりに、多型の乏しいHLA-Gを出す。古典的HLAが無い細胞は本来ならNK細胞に「missing self」として攻撃されるが（Q36・Q62と同じ原理）、HLA-Gが母体NK細胞の抑制性受容体に結合してこれを止める。　▶該当スライド：自己免疫疾患 p6",
  "choiceNotes": [
   "誤り。守るべき相手は母体側の免疫細胞。",
   "誤り。胎児のNK細胞は自分自身を攻撃しない。",
   "誤り。",
   "誤り。母親のT細胞も関わるが、HLA-Gが直接抑えるのはNK細胞。",
   "正しい＝正解。HLA-Gが母体NK細胞の抑制性受容体に結合して傷害を防ぐ。"
  ],
