  "id": "immunology2-2025-042",
  "year": "2025年度",
  "category": "免疫学（2年次）",
  "field": "T細胞・サイトカイン",
  "question": "炎症部位に好中球を集める作用がある T 細胞はどれか。",
  "choices": [
   "Th1",
   "Th2",
   "Th17",
   "Tfh",
   "Treg"
  ],
  "answer": 2,
  "explanation": "ヘルパーT細胞のサブセットは「どの敵に、どの実行部隊を呼ぶか」で整理する。Th1はIFN-γでマクロファージを活性化して細胞内寄生菌に、Th2はIL-4・IL-5・IL-13で好酸球と肥満細胞を動かして寄生虫とアレルギーに、Th17はIL-17・IL-22で好中球遊走性ケモカイン（CXCL8など）と抗菌ペプチドを誘導して細胞外細菌・真菌に対応する。好中球＝Th17と直結させる。　▶該当スライド：T細胞性免疫応答2 p6・p7／寄生虫・アレルギー p18・p19",
  "choiceNotes": [
   "誤り。Th1はIFN-γでマクロファージを活性化する（Q49・Q52）。",
   "誤り。Th2は好酸球と肥満細胞を動かす（Q44・Q78）。",
   "正しい＝正解。IL-17がCXCL8などを誘導し好中球を動員する。",
   "誤り。TfhはB細胞の抗体応答を助ける（Q19・Q43）。",
   "誤り。Tregは免疫応答を抑制する（Q40）。"
  ],
