   "正しい＝正解。CTLA-4を介するTregの抑制機能を減弱させる。",
   "誤り。CD28のように直接活性化シグナルを入れる薬ではない。",
   "正しい＝正解。CTLA-4とB7の抑制的相互作用を遮断する。"
