   "誤り。PNHはGPIアンカー合成異常でDAF（CD55）・CD59を失い、補体による溶血が起こる病気。補体制御因子側の異常。",
   "誤り。関連が全くないわけではないが、C4欠損症の典型ではない。",
   "正しい＝正解。古典経路前半成分の欠損ではSLE様の自己免疫疾患が高頻度に生じる。"
