  "question": "B 細胞受容体遺伝子再編成で、最初に germline transcription が起こるのはどの場所か。",
  "choices": ["重鎖 VD セグメント", "重鎖 DJ セグメント", "重鎖 VJ セグメント", "軽鎖 VJ セグメント", "軽鎖 JC セグメント"],
  "answer": 1,
  "explanation": "抗体遺伝子の再編成には順番があり、重鎖のD–J結合 → 重鎖のV–DJ結合 → （pre-BCRのチェック）→ 軽鎖のV–J結合、と進む。germline transcription（再編成前の生殖細胞型の転写）は「これから組み換える領域のクロマチンを開く合図」なので、最初に起こるのは最初に組み換わる重鎖のD–J領域である。重鎖にだけDセグメントがあり、軽鎖はV–Jだけという構造の違いもここで確認しておく。　▶該当スライド：先天性免疫不全症 p54・55／老化と免疫 p33・34",
  "choiceNotes": [
   "誤り。V–D（正しくはV–DJ）の結合はD–Jの後。順序が逆。",
   "正しい＝正解。重鎖はD–J再編成から始まるので、まずD–J領域が転写可能になる。",
   "誤り。重鎖はVとJが直接つながることはない。間に必ずDが入る。",
   "誤り。軽鎖の再編成は重鎖が完成しpre-BCRのチェックを通ってから。",
   "誤り。J–Cは再編成ではなくスプライシングでつながる部分。"
  ],
