   "誤り。γはIgGの重鎖の名前で、BCRの情報伝達分子ではない。",
   "誤り。δはIgDの重鎖。ナイーブB細胞はIgMとIgDを共発現するが、伝達を担うのはIgα/βである。",
   "誤り。εはIgEの重鎖。Fcε受容体（Q27）と混同しない。"
