  "choiceNotes": [
   "誤り。HLA-Aは多型性の高いクラスI分子。",
   "誤り。HLA-BはHLAの中で最も多型性が高い。",
   "誤り。HLA-Cも多型性が高い（NK細胞のKIRのリガンドとしても重要）。",
   "正しい＝正解。DRα鎖はほとんど多型を持たない。",
   "誤り。DRβ鎖は多型性が高く、移植の適合検査の対象になる。"
  ],
