  "question": "それぞれの細胞間情報伝達において、抗原非特異的に情報を伝えるのはどれか。",
  "choices": ["制御性 T 細胞—樹状細胞", "ヘルパーT 細胞—NK 細胞", "ヘルパーT 細胞—マクロファージ", "細胞傷害性 T 細胞—樹状細胞", "細胞傷害性 T 細胞—標的細胞"],
  "answer": 1,
  "explanation": "細胞間の情報伝達には、TCRがMHC＋ペプチドを見る「抗原特異的な接触」と、サイトカインを介した「抗原非特異的な伝達」がある。ヘルパーT細胞がNK細胞に働きかけるときはIL-2やIFN-γといった可溶性因子が主役で、NK細胞は抗原受容体を持たないためMHC拘束性の接触は起こり得ない——つまり必ず抗原非特異的になる。他の組み合わせはいずれもT細胞が相手のMHC上のペプチドを見ながら接触する場面（Th–マクロファージはMHC II、CTL–標的細胞はMHC I）なので抗原特異的である。　▶該当スライド：サイトカインと免疫制御 p2・3",
  "choiceNotes": [
   "誤り。TregはCTLA-4で樹状細胞のB7を奪うなど、抗原提示の場で接触して働く。",
   "正しい＝正解。NK細胞は抗原受容体を持たないため、ヘルパーT細胞からの情報はサイトカインを介した抗原非特異的なものになる。",
   "誤り。Th1はマクロファージのMHC II上のペプチドを認識してからIFN-γを渡す。",
   "誤り。CTLと樹状細胞の相互作用もMHC I／ペプチドを介する。",
   "誤り。CTLが標的細胞を殺すのはMHC Iに提示された抗原を認識したときだけ＝抗原特異的の典型。"
  ],
