  "answer": 0,
  "explanation": "接触性皮膚炎はIV型（遅延型）過敏反応で、金属イオン（ニッケル・クロムなど）がハプテンとして皮膚のタンパク質に結合し、ランゲルハンス細胞が所属リンパ節へ運んでT細胞を感作する。再曝露から24〜48時間後にTh1がIFN-γを出してマクロファージを活性化し、湿疹が生じる。ここは同じ接触性皮膚炎でも起因物質によって主役が変わる点に注意が必要で、R7で出題されたウルシ（ペンタデカカテコール＝脂溶性化学物質）については授業スライドが「CD8陽性T細胞による細胞傷害」と名指ししている。金属＝Th1、ウルシ＝CD8陽性T細胞、と対にして覚えておく。　▶該当スライド：寄生虫・アレルギー p10・p54・p55",
  "choiceNotes": [
   "正しい＝正解。金属ハプテンに対する遅延型過敏反応で、Th1が中心になる。",
   "誤り。Th2はI型アレルギーと蠕虫免疫の担当。",
   "誤り。Th17は好中球性炎症（乾癬など）に関わるが、本問の答えとしては選ばない。",
   "誤り。Tregは応答を抑える側。",
   "誤り。細胞傷害性T細胞はウルシによる接触性皮膚炎で名指しされる細胞（スライドp57）。金属では選ばない。"
  ],
