  "question": "ヒトパピローマウイルスで起こる可能性のある疾患はどれか。",
  "choices": ["胃がん", "肺がん", "肝臓がん", "子宮頸がん", "子宮体がん"],
  "answer": 3,
  "explanation": "ウイルス発がんは「どのウイルスがどのがんを起こすか」の対応で覚える。HPV（16型・18型など高リスク型）→子宮頸がん・中咽頭がん、HBV/HCV→肝細胞がん、EBV→バーキットリンパ腫・上咽頭がん、HTLV-1→成人T細胞白血病、KSHV→カポジ肉腫。胃がんはウイルスではなくヘリコバクター・ピロリ（細菌）が主因である。HPVのE6・E7蛋白がp53とRbを不活化することが発がん機序で、これらはウイルス由来の腫瘍抗原としてT細胞の標的になるため、予防にワクチンが有効（Q3の風疹とは接種の目的が違う点も対比になる）。",
  "choiceNotes": [
   "誤り。胃がんの主要な原因はヘリコバクター・ピロリ感染。",
   "誤り。肺がんの主因は喫煙などの環境因子。",
   "誤り。肝細胞がんはB型・C型肝炎ウイルスが主因。",
   "正しい＝正解。HPVは子宮頸がんの主要な原因。",
   "誤り。子宮体がんはエストロゲン関連の因子が主で、HPVとの関連は乏しい。"
  ],
