   "誤り。学童期には胸腺実質の退縮が始まるが、レパトアの完成はもう少し後。",
   "正しい＝正解。多様なレパトアはおよそ20歳＝成人期までに確立される。",
   "誤り。壮年期以降はむしろ多様性が失われていく。"
