  "explanation": "自然免疫による局所炎症は「認識 → 伝達 → 血管の変化 → 細胞の動員」という4段の流れで書くと減点されにくい。認識はTLRによるPAMPs認識（マーク問題のQ5と同じ話）、伝達は炎症性サイトカイン（TNF-α・IL-1β・IL-6）、血管の変化は内皮の透過性亢進と接着分子の発現、動員はケモカイン（CXCL8など＝Q71）による走化である。血漿成分が漏れ出ることで補体や抗体という液性因子も現場に届く、という点まで書けると「なぜ腫れるのか」が説明できたことになる。指定語句は4つとも入れないと大きく減点されるので、書き出す前に語句へ印を付けてから文章を作ること。",
