  "modelAnswer": "老化現象に伴い、\n・骨髄系細胞（好中球・単球など）が相対的に増加し、慢性的な炎症が生じ易くなっている\n・炎症性サイトカインの基線値が上昇し、慢性的な炎症が生じている\n・慢性的な炎症のため、病原体に対する応答性が低下し、生体防御能が低下している\nなど",
  "explanation": "免疫老化には「静かなのに燃えている」という一見矛盾した特徴がある。造血幹細胞が骨髄系へ偏るため好中球・単球の割合が増え、老化細胞が出すSASP（老化関連分泌形質）も加わって、IL-6やTNF-αといった炎症性サイトカインの基線値が慢性的に高くなる（inflammaging）。ところが、いざ病原体が来たときの反応性はむしろ鈍く、貪食能・走化能・ワクチン応答が低下する。つまり「常に弱く燃えているが、いざというとき燃え上がれない」状態である。3点の設問なので、①細胞の内訳の変化 ②慢性炎症 ③応答性の低下、の3点を箇条書きで並べるのが確実。獲得免疫側（胸腺退縮・ナイーブT細胞の減少＝マーク問題Q77〜79）と混ぜないよう、設問が「自然免疫」を訊いていることに注意する。",
