  "modelAnswer": "タンパク質を電気泳動法により分子量の順に分離する。メンブレンに吸着（転写）させる。メンブレンと抗体の非特異的な結合を防ぐため、ブロッキング処理を行う。目的のタンパク質に対する特異的な抗体による一次抗体反応、一次抗体に対する酵素標識二次抗体反応を行う（抗体反応の記載は必須。欠けると減点1）。続いて酵素反応により発色（または発光）させたバンドを検出する。",
  "explanation": "ウエスタンブロッティングは「分けて・写して・塞いで・当てて・光らせる」の5工程で覚える。①SDS-PAGEで変性させたタンパク質を分子量順に分離 ②ゲルからPVDFやニトロセルロースのメンブレンへ電気的に転写 ③スキムミルクやBSAでメンブレンの空き地を埋めるブロッキング（これを省くと全面が真っ黒になる）④目的タンパクに対する一次抗体 → その一次抗体を認識する酵素標識（HRPなど）二次抗体 ⑤基質を加えて酵素反応で発色・発光させ、バンドとして検出。二次抗体を使う理由は、シグナルの増幅と、標識抗体を種ごとに使い回せる経済性にある。図のようにリン酸化型（p-ERK）と総量（ERK）、内部標準（β-アクチン）を並べるのは、「タンパク量そのものが増えたのではなく、リン酸化の割合が変わった」ことを示すためで、実験デザインの定石である。",
