  "answer": 3,
  "explanation": "トキソイド（toxoid）は、細菌の外毒素をホルマリンなどで処理して毒性だけを失わせ、抗原性は残したものである。ジフテリアと破傷風がその代表で、いずれも「菌そのものではなく毒素が病気を起こす」タイプの感染症なので、毒素を中和する抗体さえ作らせれば発症を防げる。この発想の原点は北里・ベーリングの抗毒素血清療法（Q1）で、受動免疫（抗体を投与する）を能動免疫（抗体を作らせる）に置き換えたのがトキソイドである。DPT-IPVの「D」と「T」がトキソイド、「P」（百日咳）が成分ワクチンにあたる。",
  "choiceNotes": [
   "誤り。弱毒生ワクチンは病原体そのものを弱毒化したもので、毒素の無毒化ではない。",
   "誤り。不活化ワクチンは病原体全体を殺して用いる方式。毒素だけを狙ったものではない。",
   "誤り。mRNAワクチンは抗原蛋白の設計図を投与し、体内で抗原を作らせる方式。",
   "正しい＝正解。毒素の毒性を失わせ抗原性を残したものがトキソイド。ジフテリア・破傷風が代表。",
   "誤り。コンポーネント（成分）ワクチンは病原体の一部の成分を精製して用いる方式。百日咳や肺炎球菌が該当する。"
  ],
  "slideRefs": []
