  "answer": 0,
  "explanation": "プラウスニッツ・キュストナー（P-K）反応は、魚アレルギー患者の血清を健常者の皮内に注射しておき、後からその部位に抗原を接種すると即時型の膨疹・発赤が再現される、という古典的な実験である。「血清（＝液性因子）で感作が移せる」「反応が数分で出る」という2点から、原因がIgEを介したマスト細胞の脱顆粒であると分かる。すなわちGell & Coombs分類のⅠ型（アナフィラキシー型）である。ちなみにこの実験で移った液性因子こそが後にIgEと同定された（レアギン）。現在は肝炎ウイルス感染の危険があるため実施されない。　▶該当スライド：寄生虫・アレルギー p9",
