  "answer": 4,
  "explanation": "パターン認識受容体は「どこで待ち構えているか」で3群に分けると整理できる。①細胞膜上のTLR（TLR1/2/4/5/6＝細菌の膜成分やべん毛）②エンドソーム内腔のTLR（TLR3＝dsRNA、TLR7/8＝ssRNA、TLR9＝非メチル化CpG DNA）③細胞質（サイトゾル）のセンサー（RIG-I/MDA5＝ウイルスRNA、NOD様受容体＝細菌の細胞壁成分、cGAS-STING＝細胞質DNA）。核酸を見るTLRがわざわざエンドソームに置かれているのは、自己の核酸に反応しないためである。設問は「細胞内にある受容体のうち、エンドソームではなく細胞質にあるもの」を訊いており、RIG-Iが該当する。RIG-Iが検知したウイルスRNAはI型IFN産生につながる（Q73）。　▶該当スライド：老化と免疫 p22",
  "choiceNotes": [
   "誤り。TLR3はエンドソーム内で二本鎖RNAを認識する。",
   "誤り。TLR7はエンドソーム内で一本鎖RNAを認識する。pDCのI型IFN産生に関わる（Q43）。",
   "誤り。TLR8もエンドソーム内で一本鎖RNAを認識する。",
   "誤り。TLR9はエンドソーム内で細菌・ウイルス由来の非メチル化CpG DNAを認識する。",
   "正しい＝正解。RIG-Iは細胞質（サイトゾル）でウイルスRNAを認識するRNAヘリカーゼ型センサー。"
  ],
