  "explanation": "RhD陰性の母体がRhD陽性児を妊娠すると、分娩時などに胎児赤血球が母体へ流入して母体が感作され、次子で抗D IgGが胎盤を通り新生児溶血性疾患を起こす。予防の考え方は「母体のB細胞が抗原を認識する前に、投与した抗D抗体で胎児赤血球を覆い隠して排除してしまう」というもの（抗体によるフィードバック抑制）。標準的な投与は、①妊娠28週前後の予防的投与 ②RhD陽性児の分娩後72時間以内の投与、の2回である。数字が問われるので「28週」と「72時間」はそのまま覚える。48時間ではなく72時間、という細かい引っかけが選択肢dに仕込まれている。",
