  "answer": 3,
  "explanation": "抗原提示の原則は「細胞質内（内因性）の抗原 → プロテアソーム → TAP → MHC class I」「細胞外（外来性）の抗原 → エンドソーム／リソソーム → MHC class II」である。この原則にはそれぞれ例外があり、外来性抗原をclass Iに載せるのがクロスプレゼンテーション、逆に細胞質内抗原をclass IIに載せるのがオートファジーを介した経路である。胸腺髄質上皮細胞（mTEC）は、AIRE（Q36）の働きで本来は他の臓器でしか作られない自己蛋白を無理やり発現させるが、それらの多くは細胞質や核にある。それをCD4陽性胸腺細胞の負の選択に使うにはclass IIに載せなければならず、そこでオートファゴソームがリソソーム系と融合する経路が使われる。「CD4系の自己寛容を作るための例外経路」と理解すると忘れない。　▶該当スライド：T細胞の分化 p26・p27",
