   "誤り。MHC class Iを介したCD8活性化が主体ではない。",
   "誤り。結合するのはclass Iではなくclass IIである。",
   "正しい＝正解。ペプチド結合溝の外側に結合し、TCRのVβ鎖と架橋する。",
   "誤り。通常の抗原ペプチドのように溝の中に収まるのではない。プロセシングも受けない。"
