  "field": "T細胞・サイトカイン",
  "question": "抗原提示細胞上に発現し、T 細胞に対して CTLA-4 を介して不活性化シグナルを入れる分子はどれか。",
  "choices": ["B7", "CD28", "CD40", "PD-L1", "CTLA-4"],
  "answer": 0,
  "explanation": "APC上のB7（CD80/CD86）は、T細胞側の2つの受容体と結合しうる。CD28に結合すれば第2シグナル（共刺激）となりT細胞は活性化するが、活性化後に遅れて出てくるCTLA-4に結合すると逆に抑制シグナルとなる。CTLA-4はCD28よりB7への親和性が高いため、時間が経つと競り勝ってブレーキがかかる——同じリガンドで踏み込みと制動を切り替える巧妙な設計である。ここを外れるとイピリムマブ（抗CTLA-4抗体）による免疫チェックポイント阻害療法の説明ができない。もう一つの主要チェックポイントはPD-1/PD-L1で、こちらは記述設問3の題材である。「B7-CD28/CTLA-4」と「PD-L1-PD-1」の2組を混ぜないこと。　▶該当スライド：T細胞性免疫応答１ p28／腫瘍免疫 p32",
  "choiceNotes": [
   "正しい＝正解。APC上のB7（CD80/CD86）がCTLA-4に結合すると抑制シグナルが入る。",
   "誤り。CD28はT細胞側の共刺激受容体で、B7に結合して活性化シグナルを入れる。",
   "誤り。CD40はB細胞などに発現し、CD40Lを受け取る分子（Q22）。",
   "誤り。PD-L1はPD-1のリガンドで、別のチェックポイント経路（記述設問3）。",
   "誤り。CTLA-4は抑制を受け取るT細胞側の受容体そのもの。APC上の分子ではない。"
  ],
