   "誤り（＝あてはまる）。細胞内の代謝異常が特徴の一つとして挙げられている。",
   "正しい＝正解（＝あてはまらない）。老化T細胞では細胞傷害活性は維持される。低下するのは疲弊T細胞の方。",
   "誤り（＝あてはまる）。テロメラーゼ活性の低下とテロメア短縮がみられる。"
