    "modelImage": "images/immunology2/answers/2023-w02-model.webp",
    "modelImageAlt": "1個の抗原が2本のBCRを橋渡しして架橋し、それぞれのBCRに黒い長方形で描かれたIgα/βが付随し、その外側に白い長方形のチロシンキナーゼが集まっている模範図",
    "aspectRatio": 1.5,
