  "question": "PD-L1 を発現する腫瘍細胞に対して、抗 PD-1 抗体を用いた免疫チェックポイント阻害療法が奏効した。T 細胞側に必要な分子を1つ記入し、この抗 PD-1 抗体が奏効した理由を図を使って簡潔に説明しなさい。なお、免疫チェックポイント阻害療法が効く理由は複数考えられるが、ここでは腫瘍細胞と腫瘍特異的細胞傷害性 T 細胞の関係に限定して説明すること。（5点）",
