  "question": "過敏反応 Gell & Coombs分類Ⅱ型が主要な病態であるのはどれか。",
  "choices": ["SLE", "急性蕁麻疹", "接触性皮膚炎", "アレルギー性鼻炎", "Rh血液型不適合妊娠"],
  "answer": 4,
  "explanation": "Ⅱ型は「細胞や組織に固定された抗原に抗体が直接結合し、補体や食細胞、ADCCによってその細胞が壊される」型である。Rh陰性の母体がRh陽性児の赤血球で感作されると抗D抗体（IgG）ができ、次回妊娠時に胎盤を通過して胎児赤血球に結合し、脾臓のマクロファージによる破壊と補体による溶血を起こす——これが新生児溶血性疾患で、まさにⅡ型の典型である。予防には分娩後72時間以内の抗D免疫グロブリン投与を行う。他の選択肢は、SLEが免疫複合体によるⅢ型（Q64）、急性蕁麻疹とアレルギー性鼻炎がIgEによるⅠ型、接触性皮膚炎がT細胞によるⅣ型（Q63）である。　▶該当スライド：寄生虫・アレルギー p9／自己免疫疾患 p26・p30／移植免疫 p3",
  "choiceNotes": [
   "誤り。SLEは自己抗体と核抗原の免疫複合体が沈着するⅢ型が中心。",
   "誤り。急性蕁麻疹は肥満細胞の脱顆粒によるⅠ型。",
   "誤り。接触性皮膚炎はT細胞が関わるⅣ型（遅延型）。",
   "誤り。アレルギー性鼻炎はIgEを介するⅠ型。",
   "正しい＝正解。抗D抗体が胎児赤血球に結合して溶血を起こすⅡ型である。"
  ],
