  "explanation": "老化T細胞（senescent T cell）は、分裂を繰り返した末にテロメアが短縮してテロメラーゼ活性が落ち、増殖が止まった細胞である。ミトコンドリア機能が傷んで活性酸素種が増え、代謝が乱れ、SASP（senescence-associated secretory phenotype）としてIL-6やTNF-αなど炎症性サイトカインを撒き散らして周囲を慢性炎症の場に変えていく。ところが「増殖できない＝殺せない」ではないところがこの細胞の厄介な点で、老化T細胞は細胞傷害活性をむしろ保っている（NKG2Dやパーフォリンの発現が上がる例も報告されている）。だから選択肢dの「細胞傷害活性の低下」が当てはまらない特徴になる。これは疲弊T細胞（exhausted T cell：PD-1高発現で機能低下、チェックポイント阻害で可逆）とは別物で、老化は不可逆・疲弊は可逆という対比で整理しておくとよい。　▶該当スライド：老化と免疫 p45",
