  "explanation": "この設問は「何を検出しているか」を1つずつ言い換えれば解ける。中和試験は患者血清中の中和抗体がウイルスの感染性を消せるかを見る検査、白血病の解析検査は蛍光標識抗体で表面抗原（CD分子）を染めてフローサイトメトリーにかける検査、クロマチン免疫沈降（ChIP）は目的の転写因子やヒストン修飾に対する抗体でDNA-蛋白複合体を釣り上げる方法、新型コロナの簡易検査キット（抗原定性検査）はイムノクロマトによる抗原抗体反応——ここまで4つはすべて抗体を使う。残るPCR検査だけが核酸を鋳型に増幅して塩基配列を検出する方法で、抗体はいっさい登場しない。抗原検査とPCR検査の原理の違い（抗原抗体反応か核酸増幅か）は、感度・所要時間の違いとあわせて臨床でも問われるところである。　▶該当スライド：免疫学的検査法 p13・p17・p23",
