    "label": "IgG抗体の図（6つの部位を書き入れる）",
    "prompt": "Y字型の抗体を描き、重鎖・軽鎖・Fab・Fc・可変部・定常部の6つに名前を付けてください。1枚に描き切れなければ、鎖と断片を示す図／ドメインを示す図の2つに分けても構いません。",
    "modelImage": "images/immunology2/answers/2022-w02-model.webp",
    "modelImageAlt": "Y字型のIgGを2つ描いた模範図。左の図は2本の長い重鎖と2本の短い軽鎖を描き分け、上の2本の腕をFab、下の柄の部分をFcと示している。右の図は同じY字を4つずつのドメインに区切り、両腕の先端側を可変部、それ以外を定常部と示している",
    "aspectRatio": 2.1,
