  "modelAnswer": "特異抗体をプレートに固着させる。試料を加え抗体と反応させる。特異抗体と別のエピトープを持つ酵素標識抗体を反応させる。基質を加えて酵素と反応させ、発色を測定する。",
  "explanation": "Sandwich ELISAは、測定したい抗原を2種類の抗体で上下から挟み込む（サンドイッチする）ところから名前が付いている。手順は4段で、指定語句がそのまま各段の見出しになっている。\n\n①捕捉抗体の固相化——測定対象に対する特異抗体をプレートに吸着させ、余った表面をBSAなどでブロックして非特異的な吸着を防ぐ。②試料の添加——試料中の抗原だけが捕捉抗体に捕まり、他の蛋白は洗浄で流される。この洗浄工程があるおかげで、血清のような夾雑物だらけの試料でも測れる。③検出抗体の添加——捕捉抗体とは別のエピトープを認識する酵素標識抗体（HRPやアルカリホスファターゼを結合させたもの）を加える。同じエピトープを見る抗体では、すでに捕捉抗体が占めていて結合できないため、必ず「別のエピトープ」でなければならない——ここが設問がエピトープという語を指定している理由である。④発色——基質（HRPならTMBなど）を加えると酵素反応で色が付き、その吸光度を測る。抗原量が多いほど結合する標識抗体が増えるので、発色は抗原濃度に比例し、既知濃度の標準曲線から定量できる。\n\n他の型と混同しないこと。直接ELISAは試料そのものをプレートに貼り付けてから標識抗体で検出する方法（スライドの「酵素免疫測定法」の図）で、抗原を精製する必要がない代わりに特異性が落ちる。間接ELISAは抗原を貼り、患者血清中の抗体を捕まえ、抗ヒトIgG標識抗体で検出する方法で、抗体価の測定に使う（新型コロナのIgG/IgM検出がこの型）。Sandwich ELISAはこの中で最も特異性と感度が高く、サイトカインや腫瘍マーカーの定量に使われる。\n\n答案は模範解答のように4文並べるだけでよい。ただし「別のエピトープ」を落とすと、なぜ2種類の抗体が要るのかが説明できず減点される。　▶該当スライド：免疫学的検査法 p16",
