  "modelAnswer": "細胞懸濁液とシース液の流れによりラミナーフローが形成される。細胞は一列に並びレーザーを通過し、この時に回収するターゲット細胞が決定される。水流に荷電をかけ、ターゲット細胞が含まれる荷電された液滴が形成される。荷電された液滴は偏向板に引き寄せられ落下し、試験管に回収される。",
  "explanation": "セルソーターは、フローサイトメーターに「判定した細胞をその場で選り分ける」機能を足した装置である。原理は4段階で、指定語句がそのまま各段階の見出しになっている。\n\n①ラミナーフロー——細胞懸濁液の細い流れを、周囲を流れるシース液が包み込んで絞る（流体力学的絞り込み）。層流なので流れが乱れず、細胞は一列縦隊に並ぶ。②レーザー——フローセル内で細胞が1個ずつレーザー光を横切り、前方散乱光（大きさ）・側方散乱光（内部構造）・蛍光（標識抗体）が測定される。ここで「この細胞は回収する／しない」が瞬時に判定される。③荷電と液滴——ノズルを超音波で振動させて水流を一定間隔の液滴に切り、目的の細胞が入る液滴ができる瞬間に水流全体へ正または負の電荷をかける。こうしてターゲット細胞を含む液滴だけが帯電する。④偏向板——落下していく液滴は高電圧をかけた2枚の偏向板の間を通り、帯電した液滴だけが電気的に引き寄せられて進路を曲げ、所定の試験管に落ちる。帯電していない液滴はまっすぐ落ちて廃液へ行く。\n\n答案は、この4段階を順に1文ずつ並べるだけでよく、余計な説明は要らない。逆に語句を1つでも落とすと、その段階の説明が抜けたとみなされて減点される。なおこの設問は令和5年度の設問7とまったく同じ問題で、模範解答も同一である——過去問を回しておく価値がそのまま点になる出題といえる。　▶該当スライド：免疫学的検査法 p30・p31",
